import { createContext, runInContext } from 'node:vm'

type CookieJar = {
  cookie: string
}

/**
 * Reads the __test cookie generated by the CMS hosting challenge script.
 */
export async function solveHostChallenge(html: string, aesScript: string): Promise<string> {
  const scripts = [...html.matchAll(/<script[^>]*>([\s\S]*?)<\/script>/g)].map((match) => match[1])
  const jar: CookieJar = { cookie: '' }
  const sandbox = {
    document: {
      set cookie(value: string) {
        jar.cookie = value
      },
      get cookie(): string {
        return jar.cookie
      }
    },
    location: {
      href: ''
    }
  }
  const context = createContext(sandbox)
  runInContext(aesScript, context)
  scripts.forEach((script) => {
    if (script) {
      runInContext(script, context)
    }
  })
  const cookieMatch = jar.cookie.match(/__test=([^;]+)/)
  if (!cookieMatch?.[1]) {
    throw new Error('CMS host challenge cookie was not generated')
  }
  return cookieMatch[1]
}
